nts":[{"id":"c3f4132","elType":"widget","settings":{"html":"<style>
    .logo-section {
        background-color: #2087c9;
        padding: 25px 0;
        width: 100%;
        position: relative;
        overflow: hidden;
    }
    .logo-container {
        margin: 0 auto;
        display: flex;
        width: 800px;
        gap: 30px;
        padding: 0 20px;
        animation: scroll 20s linear infinite;
        box-sizing: border-box;
    }
    @keyframes scroll {
        0% { transform: translateX(0); }
        100% { transform: translateX(-100%); }
    }
    .logo-item {
        background: inherit;
        padding: 0;
        transition: all 0.3s ease;
        display: flex;
        align-items: center;
        justify-content: center;
        min-width: 140px;
        height: 100px;
        flex-shrink: 0;
        box-sizing: border-box;
    }
    .logo-item img {
        max-width: 130px;
        max-height: 80px;
        object-fit: contain;
        filter: brightness(0) invert(1);
    }

    /* Rotessa, Hubdoc, ADP: 90px */
    .logo-item.google-images img,
    .logo-item.hubdoc img,
    .logo-item img[src*="adp-l"] {
        max-height: 90px !important;
        max-width: 140px !important;
    }

    /* Native color logos */
    .logo-item.xero img,
    .logo-item.google-images img,
    .logo-item.odoo img,
    .logo-item.hubdoc img,
    .logo-item.stripe img,
    .logo-item img[src*="quickbooks.png"],
    .logo-item img[src*="adp-l"] {
        filter: none;
    }

    .logo-item.hubdoc,
    .logo-item img[src*="adp-l"] ~ .logo-item {
        background: #2087c9;
    }

    .logo-item:hover {
        transform: translateY(-3px);
        box-shadow: 0 8px 20px rgba(0,0,0,0.2);
    }
</style>

