/* FULL WIDTH WRAPPER */
.cpa-wrapper {
  width: 100%;
  padding: 60px 80px;
  box-sizing: border-box;

  display: flex;
  justify-content: center;
  gap: 40px;
  flex-wrap: wrap;

  background: #f5f8fc;
}

/* CARD */
.cpa-card {
  flex: 1;
  min-width: 320px;
  max-width: 520px;

  display: flex;
  background: #ffffff;
  border-radius: 18px;
  box-shadow: 0 8px 25px rgba(0,0,0,0.06);
  padding: 30px;
  gap: 25px;
  align-items: center;

  transition: all 0.3s ease;
}

.cpa-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 14px 35px rgba(0,0,0,0.1);
}

/* IMAGE */
.cpa-card img {
  width: 190px;
  height: 230px;
  object-fit: cover;
  border-radius: 14px;
  flex-shrink: 0;
}

/* INFO */
.cpa-info {
  display: flex;
  flex-direction: column;
  font-family: Arial, sans-serif;
}

.cpa-info h3 {
  font-size: 22px;
  margin: 0 0 8px;
  font-weight: 700;
  color: #111;
}

/* BIO LINK (Blue Like Screenshot) */
.cpa-info a.bio-link {
  font-size: 15px;
  color: #0077b5;
  text-decoration: none;
  margin-bottom: 10px;
}

.cpa-info a.bio-link:hover {
  text-decoration: underline;
}

/* ROLE */
.cpa-info strong {
  font-size: 15px;
  margin-bottom: 10px;
  color: #333;
}

/* PHONE + EMAIL */
.cpa-info a.contact-link {
  font-size: 14px;
  color: #444;
  text-decoration: none;
  margin-bottom: 6px;
}

.cpa-info a.contact-link:hover {
  color: #0077b5;
}

/* MOBILE */
@media (max-width: 768px) {
  .cpa-wrapper {
    padding: 30px 20px;
  }

  .cpa-card {
    flex-direction: column;
    text-align: center;
  }

  .cpa-card img {
    width: 100%;
    max-width: 280px;
    height: auto;
  }
}
</style>

