  document.querySelectorAll('.one-location').forEach(loc => {
    loc.addEventListener('click', (event) => {
      event.preventDefault(); // prevents links too, safer to have

      // Remove active styles from all
      document.querySelectorAll('.one-location').forEach(el => {
        el.style.background = '#fff';
        el.style.borderLeft = '4px solid transparent';
      });

      // Highlight selected location
      loc.style.background = '#eef8ff';
      loc.style.borderLeft = '4px solid #0073e6';

      // Switch iframe src
      const newSrc = loc.getAttribute('data-map-src');
      document.getElementById('mapIframe').setAttribute('src', newSrc);
    });

    // Also prevent clicks on links inside location divs from navigating
    loc.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', e => e.preventDefault());
    });
  });
</script>
